<script setup>
import { computed, onMounted, ref } from 'vue'
import { getAuditLogs } from '@/api/adminPhase2'
import { formatDateTime } from '@/utils/dataAdapters'
const source=ref([]);const total=ref(0);const page=ref(1);const resource=ref('');const keyword=ref('');const rows=computed(()=>source.value.filter(x=>(!resource.value||x.resourceType===resource.value)&&(!keyword.value||`${x.user}${x.description}${x.resourceId}`.toLowerCase().includes(keyword.value.toLowerCase()))));async function load(){const result=await getAuditLogs({page:page.value,pageSize:50});source.value=result.items;total.value=result.total}onMounted(load)
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">关键操作日志</h1><p class="page-subtitle">来自数据库 audit_log 的真实、只读审计记录；计划生成提交与管理员确认/退回均在此追溯。</p></div><div class="page-actions"><el-input v-model="keyword" clearable placeholder="用户、描述或资源编号"/><el-select v-model="resource" clearable placeholder="全部资源"><el-option v-for="item in ['FARM','PLOT','USER','CULTIVATION_TEMPLATE','MANAGEMENT_PLAN','FARM_TASK','PLAN_CHANGE_REQUEST']" :key="item" :label="item" :value="item"/></el-select></div></div><section class="content-panel"><el-table :data="rows"><el-table-column label="时间" min-width="170"><template #default="s">{{formatDateTime(s.row.createdAt)}}</template></el-table-column><el-table-column prop="user" label="操作用户"/><el-table-column prop="action" label="动作"/><el-table-column prop="resourceType" label="资源类型"/><el-table-column prop="resourceId" label="资源编号"/><el-table-column prop="description" label="说明" min-width="240"/><el-table-column prop="ip" label="IP"/></el-table><el-pagination v-model:current-page="page" :page-size="50" :total="total" layout="prev, pager, next, total" @current-change="load"/></section></div></template>
<style scoped>.page-actions .el-input{width:230px}.page-actions .el-select{width:180px}</style>
